INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 36, 'theory', 'Quiz: reactivity and signals');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 36, 0, 'How does a signal find out that an effect has read it?', '["The effect lists the signals by hand", "Before running, the effect writes itself into a global \"current observer\" variable, and the signal looks there on read", "The signal scans the source code", "Through DOM events"]', 1, 'Automatic tracking: the signal''s getter adds the current effect to its subscribers. After the run the variable is restored.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 36, 1, 'Why does an effect rebuild its subscriptions on every run?', '["To slow things down", "The set of signals read depends on conditions: the subscription must match the actual reads", "It is a browser requirement", "To clear the browser''s memory"]', 1, 'Branching changes the set of dependencies. Old subscriptions are removed, and new ones are collected during the run.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 36, 2, 'What is a glitch in a reactive system?', '["A compile error", "A consumer briefly sees an inconsistent state: some values new, some old", "A memory leak", "An infinite loop"]', 1, 'In a diamond dependency, a naive recomputation runs the consumer before all the intermediate values have been updated.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 36, 3, 'What does batch(fn) do?', '["Runs fn in another thread", "Postpones running effects until fn ends: each needed effect runs once", "Cancels changes", "Deletes effects"]', 1, 'Several signal writes inside batch cause no intermediate runs; after leaving it, the effects run once each.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 36, 4, 'Why won''t items.push(x) update the interface if items is stored in an ordinary signal?', '["push is forbidden in JS", "The array reference did not change: the signal compares with Object.is; you need to write a new array", "Signals don''t store arrays", "push works asynchronously"]', 1, 'An in-place mutation does not change the reference. Use either immutable updates (set([...items, x])) or proxy reactivity.');
